<?php namespace App\Filament\Resources\UserResource\Pages; use App\Filament\Pages\EditAuditedRecord; use App\Filament\Resources\UserResource; class EditUser extends EditAuditedRecord {protected static string $resource=UserResource::class; protected function mutateFormDataBeforeSave(array $data):array{if($this->record->is(auth()->user())&&($data['role']!=='admin'||$data['status']!=='active'))throw \Illuminate\Validation\ValidationException::withMessages(['role'=>'Vous ne pouvez pas vous retirer vos propres accès.']);return $data;}}
